import sys

def solve():
    input = sys.stdin.read
    data = input().strip().split()
    n = int(data[0])
    s = data[1]

    best_cost = n + 1
    best_res = None

    colors = ['R', 'G', 'B']

    for c0 in colors:
        for c1 in colors:
            if c0 == c1:
                continue
            for c2 in colors:
                if c2 in (c0, c1):
                    continue

                current_cost = 0
                res_chars = []
                for i in range(n):
                    expected = c0 if i % 3 == 0 else (c1 if i % 3 == 1 else c2)
                    if s[i] != expected:
                        current_cost += 1
                    res_chars.append(expected)

                if current_cost < best_cost:
                    best_cost = current_cost
                    best_res = "".join(res_chars)

    print(best_cost)
    print(best_res)

if __name__ == "__main__":
    solve()
